    Object.assign(dropBtn.style, {
      padding: '6px 10px', background: '#101626', color: '#cfe8ff',
      border: '1px solid #2d3b52', borderRadius: '6px', cursor: 'pointer'
    });
    dropBtn.textContent = 'Drop';
    dropBtn.addEventListener('click', () => {
