import { chromium } from '/home/pjensen/Repos/hermetic-sky/node_modules/playwright/index.mjs';
const repo = '/home/pjensen/Repos/JSHack';
const browser = await chromium.launch({executablePath:'/home/pjensen/.cache/ms-playwright/chromium_headless_shell-1243/chrome-headless-shell-linux64/chrome-headless-shell',headless:true,args:['--no-sandbox']});
try {
 for (const width of [458, 884, 1920]) {
  const page = await browser.newPage({viewport:{width,height:900},serviceWorkers:'block'});
  const errors=[];
  page.on('pageerror',e=>errors.push(e.message));
  await page.route('**/*',async route=>{
   const url=new URL(route.request().url());
   if(url.pathname==='/') return route.fulfill({contentType:'text/html',body:`<html><head><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="background:#191c20"><script type="module">import {initHUD} from '/src/display/ui/hud.js';initHUD();window.dispatchEvent(new CustomEvent('ui:updateVitals',{detail:{hp:18,maxHp:18,mana:77,maxMana:81,stamina:77,maxStamina:77}}));window.dispatchEvent(new CustomEvent('ui:updateCombatHUD',{detail:{statuses:[{key:'satiated',turns:99,stacks:1}]}}));window.dispatchEvent(new CustomEvent('ui:updateQuestTracker',{detail:{focused:{title:'Scout the Quarter',progress:9,target:12}}}));window.ready=true;</script></body></html>`});
   try {return route.fulfill({contentType:url.pathname.endsWith('.js')?'text/javascript':'application/octet-stream',body:await Deno.readFile(repo+url.pathname)});}catch{return route.abort();}
  });
  await page.goto('http://jshack.test/');
  await page.waitForFunction(()=>window.ready,{},{timeout:10000}).catch(()=>{});
  const layout=await page.evaluate(()=>[...document.querySelectorAll('[data-resource]')].map(el=>({resource:el.dataset.resource,...Object.fromEntries(['x','y','width','height'].map(k=>[k,el.getBoundingClientRect()[k]])),parent:getComputedStyle(el.parentElement).display})));
  console.log(JSON.stringify({width,errors,layout}));
  await page.screenshot({path:`/tmp/jshack-hud-${width}.png`});
  if(errors.length || layout.length!==3 || layout.some(el=>Math.abs(el.y-layout[0].y)>1) || !(layout[0].x<layout[1].x&&layout[1].x<layout[2].x)) throw new Error('HUD columns failed');
  await page.close();
 }
}finally{await browser.close();}

