  try {
    const body = await Deno.readFile(repo + (path === '/' ? 'index.html' : path.slice(1)));
    const type = path.endsWith('.js') ? 'text/javascript' : path.endsWith('.css') ? 'text/css' : path.endsWith('.html') || path === '/' ? 'text/html' : 'application/octet-stream';
