 * @param {string|number} size
 * @param {string|number} [weight]
 * @returns {string}
 */
export function canvasGlyphFont(glyph, size, weight = 900) {
  return canvasFont(size, weight, isIconGlyph(glyph) ? GAME_ICON_FONT_FAMILY : GAME_TEXT_FONT_FAMILY);
}
